document.addEventListener("DOMContentLoaded", () => {
  console.log("App UI iniciado");

  const mainWrapper = document.getElementById("main-wrapper");
  const togglers = document.querySelectorAll(".sidebartoggler");

  if (!mainWrapper) {
    console.warn("No existe #main-wrapper");
    return;
  }

  // ===============================
  // 📱 DETECTAR TAMAÑO DE PANTALLA
  // ===============================
  function setSidebarType() {
    const width = window.innerWidth;

    if (width < 1199) {
      mainWrapper.setAttribute("data-sidebartype", "mini-sidebar");
      mainWrapper.classList.add("mini-sidebar");
    } else {
      mainWrapper.setAttribute("data-sidebartype", "full");
      mainWrapper.classList.remove("mini-sidebar");
    }
  }

  // Ejecutar al iniciar
  setSidebarType();

  // Ejecutar al redimensionar (optimizado)
  let resizeTimeout;
  window.addEventListener("resize", () => {
    clearTimeout(resizeTimeout);
    resizeTimeout = setTimeout(setSidebarType, 150); // evita sobrecarga
  });

  // ===============================
  // 🔘 TOGGLER SIDEBAR
  // ===============================
  togglers.forEach((btn) => {
    btn.addEventListener("click", () => {
      const isMini = mainWrapper.classList.toggle("mini-sidebar");

      // Cambiar atributo
      mainWrapper.setAttribute(
        "data-sidebartype",
        isMini ? "mini-sidebar" : "full"
      );

      // Mostrar/ocultar sidebar (para móvil)
      mainWrapper.classList.toggle("show-sidebar");

      // Sincronizar checkbox si existe
      if (btn.type === "checkbox") {
        btn.checked = isMini;
      }
    });
  });

});